const raw = $input.first().json;
const body = raw.body || raw;

const forwarderName = String(body.forwarderName || '').trim();
const recipientEmail = String(body.recipientEmail || '').trim();
const registrationUrl = String(body.registrationUrl || '').trim();
const issuedBy = body.issuedBy || {};

const faltantes = [];
if (!forwarderName) faltantes.push('forwarderName');
if (!recipientEmail) faltantes.push('recipientEmail');
if (!registrationUrl) faltantes.push('registrationUrl');

const problemas = [];
if (faltantes.length > 0) problemas.push('Faltan campos obligatorios: ' + faltantes.join(', '));

if (recipientEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail)) {
  problemas.push('recipientEmail no tiene formato de correo');
}

// Comprobacion por prefijo a proposito: el sandbox del nodo Code NO expone el
// global URL, y usar new URL() aqui lanzaba ReferenceError que el catch se tragaba,
// rechazando URLs https perfectamente validas.
if (registrationUrl) {
  const u = registrationUrl.toLowerCase();
  const protocoloOk =
    u.startsWith('https://') ||
    u.startsWith('http://localhost') ||
    u.startsWith('http://127.0.0.1');
  if (!protocoloOk) {
    problemas.push('registrationUrl debe usar https (localhost solo se admite en pruebas)');
  }
}

const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const nombre = esc(forwarderName);
const url = esc(registrationUrl);

const html = [
  '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">',
  '<meta name="viewport" content="width=device-width, initial-scale=1"></head>',
  '<body style="margin:0;padding:24px;background:#fcf9f8;font-family:Arial,Helvetica,sans-serif;color:#1b1c1c;">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#ffffff;border:1px solid #d6c3b9;border-radius:12px;">',
  '<tr><td style="background:#421e04;color:#ffffff;padding:20px 24px;border-radius:12px 12px 0 0;">',
  '<div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;opacity:.85;">Maderas Rivero S.A. de C.V.</div>',
  '<div style="font-size:20px;font-weight:bold;margin-top:4px;">Registro de embarques</div>',
  '</td></tr>',
  '<tr><td style="padding:24px;">',
  '<p style="margin:0 0 16px;font-size:15px;line-height:1.6;">Estimados <strong>' + nombre + '</strong>:</p>',
  '<p style="margin:0 0 16px;font-size:15px;line-height:1.6;">Habilitamos un enlace para que registren directamente en nuestro sistema los embarques que operan para nosotros: referencia (MBL), naviera, SCAC, contenedores, proveedor, material y factura.</p>',
  '<p style="margin:0 0 24px;font-size:15px;line-height:1.6;">El enlace es <strong>permanente</strong>: consérvenlo y úsenlo cuantas veces necesiten, un registro por embarque. No necesitan crear cuenta ni contraseña.</p>',
  '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px;"><tr><td style="background:#421e04;border-radius:8px;">',
  '<a href="' + url + '" style="display:inline-block;padding:14px 28px;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none;">Registrar un embarque</a>',
  '</td></tr></table>',
  '<p style="margin:0 0 8px;font-size:13px;line-height:1.6;color:#70635d;">Si el botón no funciona, copien esta dirección en su navegador:</p>',
  '<p style="margin:0 0 24px;font-size:12px;line-height:1.5;word-break:break-all;color:#51443d;">' + url + '</p>',
  '<p style="margin:0;padding:12px 16px;background:#fef3c7;border-left:4px solid #92400e;font-size:13px;line-height:1.6;color:#92400e;">Este enlace es exclusivo de su organización y permite registrar embarques a nuestro nombre. Por favor no lo reenvíen fuera de su equipo de operaciones. Si sospechan que se difundió, avísennos para reemplazarlo.</p>',
  '</td></tr>',
  '<tr><td style="padding:16px 24px;border-top:1px solid #e0d9d4;font-size:12px;color:#70635d;">Mensaje automático del portal de Maderas Rivero. Para dudas, respondan a este correo.</td></tr>',
  '</table></body></html>'
].join('');

const texto = [
  'Estimados ' + forwarderName + ':',
  '',
  'Habilitamos un enlace para que registren directamente los embarques que operan para nosotros (MBL, naviera, SCAC, contenedores, proveedor, material y factura).',
  '',
  'El enlace es permanente: consérvenlo y úsenlo cuantas veces necesiten, un registro por embarque. No necesitan cuenta ni contraseña.',
  '',
  registrationUrl,
  '',
  'Este enlace es exclusivo de su organización. Por favor no lo reenvíen fuera de su equipo de operaciones.',
  '',
  'Mensaje automático del portal de Maderas Rivero.'
].join('\n');

return [{
  json: {
    valido: problemas.length === 0,
    motivo: problemas.join('. '),
    forwarder_name: forwarderName,
    to_email: recipientEmail,
    subject_email: 'Registro de embarques - Maderas Rivero',
    html_email: html,
    text_email: texto,
    issued_by: issuedBy.username || null
  }
}];
